-- ---------------------------------------------------------------------
-- Myagi presenter videos (2026-09-30). Plain MP4s on Myagi's CDN, verified
-- to load without a login. See docs/myagi-video-catalog.md. Shoes without
-- a row here show the hero photo + intro_bullets instead.
-- ---------------------------------------------------------------------
update products set video_url = 'https://myagi.rallyware.com/cdn2/uploads/5ec7c35e-a754-4e3b-9897-27452e51cccc/units/file/' || v.path
from (values
  ('supernova-rise-3', 'b4eafeb9-97f6-4146-bf28-cf469ed30009/wistia_video_XzQ9Ao.mp4'),
  ('boston-13',        '31ff97ea-0b9b-4d04-a31d-8b0f46162372/wistia_video_w9blak.mp4'),
  ('evo-sl',           'f32b1580-2fc2-4b91-9890-e9f417fbf064/wistia_video_iY4Jfr.mp4')
) as v(pid, path)
where products.id = v.pid;
